--
-- Table structure for table `kpi_measurement`
--

DROP TABLE IF EXISTS `kpi_measurement`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `kpi_measurement` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `kpi_metric_id` int unsigned NOT NULL,
  `kpi_metric_version` int DEFAULT NULL,
  `measured_value` decimal(12,4) DEFAULT NULL,
  `measurement_period_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `measurement_period_label` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `period_start_date` date NOT NULL,
  `period_end_date` date NOT NULL,
  `status` enum('green','amber','red','critical','unknown') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `measurement_note` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `raw_payload` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `post_action` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `measured_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `measured_by` int unsigned NOT NULL,
  `is_system_generated` tinyint(1) NOT NULL DEFAULT '0',
  `is_pending` tinyint(1) NOT NULL DEFAULT '0',
  `pending_reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `is_corrected` tinyint(1) NOT NULL DEFAULT '0',
  `corrected_from_id` bigint unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0',
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_metric_period` (`kpi_metric_id`,`period_start_date`),
  KEY `idx_status` (`status`),
  KEY `idx_measured_at` (`measured_at`),
  KEY `idx_measured_by_period` (`measured_by`,`period_start_date`),
  KEY `idx_metric_deleted` (`kpi_metric_id`,`is_deleted`),
  KEY `idx_corrected_from` (`corrected_from_id`),
  CONSTRAINT `fk_meas_corrected` FOREIGN KEY (`corrected_from_id`) REFERENCES `kpi_measurement` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_meas_employee` FOREIGN KEY (`measured_by`) REFERENCES `employees` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_meas_metric` FOREIGN KEY (`kpi_metric_id`) REFERENCES `kpi_metric` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

