INSERT INTO `kpi_metric` VALUES (1,1,'Delivery Commitment Accuracy (Kanban Team)','≥ 85% (senior) / ≥ 90% (lead)','higher_better',85.00,80.00,70.00,'Percentage','weekly','Jira / Kanban planning sheet','TBD — confirm in pre-go-live workshop (BRD §13.3)','(Delivered planned items ÷ committed planned items) × 100, monthly. Track unplanned urgent work separately so genuine commitment misses are visible.',0,1,'2026-06-01 09:00:00','2026-08-13 11:42:30',0,NULL,1,1),(2,1,'Unplanned Work Interruption Rate','< 20% of capacity','lower_better',20.00,25.00,35.00,'Percentage','weekly','Kanban Planning Excel','https://audev.atlassian.net/issues/?filter=11647','(Unplanned urgent work hours ÷ total planned capacity) × 100, weekly.',0,1,'2026-06-01 09:00:00','2026-07-21 16:17:38',0,NULL,1,0),(3,1,'Estimation Accuracy (SCRUM Team Nikhil)','Within ±15% variance','lower_better',15.00,20.00,30.00,'Percentage','monthly','Jira (planned vs actual effort)','TBD — confirm in pre-go-live workshop (BRD §13.3)','abs(actual hours − estimated hours) ÷ estimated hours, averaged per story, monthly. Single unit = hours.',1,1,'2026-06-01 09:00:00','2026-08-14 11:20:41',0,NULL,1,1),(4,1,'Late Scope Change Rate','< 10% of stories','lower_better',10.00,15.00,25.00,'Percentage','monthly','Jira change analysis','TBD — confirm in pre-go-live workshop (BRD §13.3)','Stories flagged \'scope-change\' after dev started ÷ total stories, monthly. Joint Lead + PO accountability; requires Jira scope-change label + comment.',0,1,'2026-06-01 09:00:00','2026-08-14 05:45:55',0,NULL,24,0),(5,1,'Critical/Urgent SLA Compliance (Kanban Team)','≥ 90% within SLA','higher_better',90.00,80.00,70.00,'Percentage','monthly','Jira (due-date adherence)','project IN (CARIT) AND priority IN (Critical, Urgent) AND type = \'Bug / Impediment\'','(On-time Critical+Urgent ÷ total Critical+Urgent) × 100, monthly via Jira due-date adherence.',1,1,'2026-06-01 09:00:00','2026-07-30 12:39:12',0,NULL,1,1),(6,2,'Code Review Rework Cost','≤ 20% rework effort','lower_better',20.00,30.00,40.00,'Percentage','bi_weekly','Jira / Code review','type = \"Bug / Impediment\" and \"Planning Development[Short text]\" ~ 26-33  AND \"Planning Development[Short text]\" ~ 26-34 AND comment ~ \"code review remark\" and comment ~ \"remark\"','(rework hours ÷ total development hours) × 100, monthly per team\n',1,1,'2026-06-01 09:00:00','2026-09-08 06:07:33',0,NULL,24,1),(7,2,'Test Coverage of Critical Paths','≥ 2 flows/story; 0 missed','higher_better',100.00,90.00,80.00,'Percentage','bi_weekly','Jira QA tab','TBD — confirm in pre-go-live workshop (BRD §13.3)','Alternate/error flows documented ÷ stories requiring them, aggregated bi-weekly. \'Alternate flow\' = error paths, boundary values, integration scenarios.',0,1,'2026-06-01 09:00:00','2026-08-13 11:57:45',0,NULL,1,0),(8,2,'Permanent Fix Ratio','≥ 90% permanent fixes','higher_better',90.00,85.00,75.00,'Percentage','monthly','Jira (fix-type field)','Jira release note & development notes','(Permanent fixes ÷ total fixes) × 100, monthly. Requires new mandatory Jira \'fix type\' (Permanent/Workaround) field set at closure.',1,1,'2026-06-01 09:00:00','2026-08-27 05:33:11',1,NULL,24,0),(9,2,'Defect Escape Rate','< 5%','lower_better',5.00,8.00,12.00,'Percentage','monthly','Consolidated RC QA sheet','TBD — confirm in pre-go-live workshop (BRD §13.3)','Defects found post-handoff ÷ total defects, monthly. Requires the RC QA sheet consolidation (enabling fix).',0,1,'2026-06-01 09:00:00','2026-08-13 11:59:34',0,NULL,1,0),(10,2,'Production Defects','< 10 per week','lower_better',10.00,12.00,15.00,'Count','weekly','Jira','project IN (CARIT) AND created >= weekstart','Count of defects by severity. Report Critical defects on a separate line.',1,1,'2026-06-01 09:00:00','2026-08-27 08:45:12',0,NULL,1,1),(11,2,'QA Reopen Rate','< 5%','lower_better',5.00,8.00,12.00,'Percentage','monthly','Jira','Filter: status transitions Done → Rework','(Bugs reopened ÷ total QA-closed bugs) × 100, monthly. Store as percentage, not raw count.',0,1,'2026-06-01 09:00:00','2026-08-13 11:57:56',0,NULL,1,0),(12,2,'Development Rework Rate','< 15% of dev effort','lower_better',15.00,25.00,35.00,'Percentage','monthly','Jira sprint reports','TBD — confirm in pre-go-live workshop (BRD §13.3)','(Rework hours on own stories ÷ total dev hours) × 100, monthly. Denominator rule: only stories where the individual was primary developer.',1,1,'2026-06-01 09:00:00',NULL,0,NULL,NULL,0),(13,2,'Testing Remark Severity Score','≤ 4 weighted remarks','lower_better',4.00,6.00,8.00,'Count','bi-weekly','Jira QA tab','TBD — confirm in pre-go-live workshop (BRD §13.3)','Severity-weighted count of unit/impact test remarks (critical edge-case weighted higher than cosmetic), bi-weekly.',1,1,'2026-06-01 09:00:00',NULL,0,NULL,NULL,0),(14,2,'Jira Hygiene Compliance','≥ 95%','higher_better',95.00,90.00,85.00,'Percentage','monthly','Jira audit','TBD — confirm in pre-go-live workshop (BRD §13.3)','Defined Jira filter (description + assignee + estimate + current status present) run monthly; (compliant ÷ total active Jiras) × 100.',1,1,'2026-06-01 09:00:00',NULL,0,NULL,NULL,0),(15,3,'RCA Submission Compliance for Critical Issues','100% within 48h','higher_better',100.00,90.00,80.00,'Percentage','monthly','RCA reports / Jira','type = \"Bug / Impediment\" and createdDate >= startOfMonth()  AND priority WAS IN (Critical)','RCA Jira created & linked within 48h of critical-issue resolution. Hard gate: critical issue cannot close without RCA.\nIf developer spend more than 8 hours to fix the issue then create RCA ticket under INT-147 + retrospective Jiras\notherwise update the Cause field with all the details',1,1,'2026-06-01 09:00:00','2026-08-27 06:12:00',0,NULL,24,0),(16,3,'Clean Release Rate','100% checklist + 0 P1/48h','higher_better',100.00,95.00,90.00,'Percentage','per_release','Release management sheet','https://1drv.ms/x/c/a83e0a26ac82ae8e/EVnYzETE3j1DrkGffnspbs4BuWUmT7WmMe2T5BBwP48ARg','Release checklist sign-off AND zero post-release P1 incidents within 48h window.\n\n',0,1,'2026-06-01 09:00:00','2026-08-14 11:26:24',0,NULL,1,0),(17,3,'Critical Issue Response Time','< 2 working hours (median)','lower_better',2.00,4.00,8.00,'Hours','monthly','Jira worklog / comments','type = \"Bug / Impediment\" and createdDate >= startOfMonth()  AND priority WAS IN (Critical)','Median time from Critical status set to first reproduction-confirmed comment. Report actual hours AND SLA-met %.\nNeed discussion\n if there are multiple jiras  how to calculate Warn threshold —  and Targeted values\n',1,1,'2026-06-01 09:00:00','2026-08-27 10:53:43',0,NULL,24,1),(18,3,'Quality-Driven Rollback Count','Zero per release','lower_better',0.00,1.00,2.00,'Count','monthly','Release incident log (Peter)','TBD — confirm in pre-go-live workshop (BRD §13.3)','Count of rollbacks attributed to quality defects, per release, from Peter\'s formalised release incident log.\n\n',0,1,'2026-06-01 09:00:00','2026-08-14 11:26:53',0,NULL,1,0),(19,3,'Validation-Gap Hotfix Count','Zero per quarter (≤1 ok)','lower_better',0.00,1.00,2.00,'Count','quarterly','Release incident log','TBD — confirm in pre-go-live workshop (BRD §13.3)','Count of hotfixes whose root cause was a missed validation step, quarterly, from release incident log.',0,1,'2026-06-01 09:00:00','2026-08-14 11:33:07',0,NULL,1,0),(20,3,'Deployment Success Rate','≥ 95%','higher_better',95.00,90.00,85.00,'Percentage','monthly','Release management sheet','https://1drv.ms/x/c/a83e0a26ac82ae8e/EVnYzETE3j1DrkGffnspbs4BuWUmT7WmMe2T5BBwP48ARg','(Deployments without rollback or P1 within 24h ÷ total deployments) × 100, per release.\n\nMostly stable, so we keep it inactive.',0,1,'2026-06-01 09:00:00','2026-08-14 11:25:49',0,NULL,1,0),(21,4,'Customer Ticket Resolution SLA Compliance (Kanban Team)','≥ 90% within SLA','higher_better',90.00,85.00,75.00,'Percentage','weekly','Zendesk (native SLA metrics)','TBD — confirm in pre-go-live workshop (BRD §13.3)','Zendesk First Reply Time + Resolution Time within SLA ÷ total tickets. Use Zendesk SLA fields, NOT developer hours logged.\nTicket start time + Ticket closed time + 4 hours SLA (Best on IST timezone 10:00AM to 7:30PM) \n',1,1,'2026-06-01 09:00:00','2026-08-27 10:59:15',0,NULL,24,1),(22,4,'Ticket Handling Accuracy','≥ 95%','higher_better',95.00,90.00,80.00,'Percentage','weekly','Zendesk','TBD — confirm in pre-go-live workshop (BRD §13.3)','Tickets not mis-classified as spam/incident + responded within SLA + not reopened within 7 days, ÷ total tickets.',0,1,'2026-06-01 09:00:00','2026-08-14 11:33:21',0,NULL,1,0),(23,4,'Management-Level Customer Escalations','Zero at exec level','lower_better',0.00,1.00,2.00,'Count','monthly','Operations escalation log','TBD — confirm in pre-go-live workshop (BRD §13.3)','Monthly count of escalations reaching CTO/MD level, from Operations escalation log, within 3 business days of period close.',1,1,'2026-06-01 09:00:00',NULL,0,NULL,NULL,0),(24,5,'End-to-End Story Ownership Rate','≥ 85% stories fully owned','higher_better',85.00,80.00,70.00,'Percentage','bi_weekly','Jira tracking / iLexius planning','https://audev.atlassian.net/issues?filter=12243','Score 0-4 per story (refinement written / dev complete / QA passed no major rework / deployed); average across period, normalised to %.',1,1,'2026-06-01 09:00:00','2026-08-14 11:24:01',0,NULL,1,0),(25,5,'Refinement Readiness','≥ 90% Definition-of-Ready','higher_better',90.00,80.00,70.00,'Percentage','monthly','Jira tracking','TBD — confirm in pre-go-live workshop (BRD §13.3)','Story is \'ready\' only if AC written + estimated + zero open questions. (ready ÷ total) × 100 monthly via Jira dashboard.',1,1,'2026-06-01 09:00:00',NULL,0,NULL,NULL,0),(26,5,'Blocker Resolution Efficiency','< 1 business day average','lower_better',1.00,2.00,3.00,'Days','bi_weekly','Jira / Teams','project = CarIT AND \'Flagged[Checkboxes]\' IS NOT EMPTY AND resolved >= startOfWeek()','Jira flag added when blocked, removed on resolution; avg(resolved − flagged) via Jira filter, bi-weekly.',0,1,'2026-06-01 09:00:00','2026-07-21 16:22:03',0,NULL,1,0),(27,5,'Productivity Improvement Impact','≥ 1/quarter w/ quantified benefit','higher_better',1.00,1.00,0.00,'Count','quarterly','Process Improvement Jira','INT-9 + improvement Jira filter','Each initiative requires: Jira ticket + peer review + documented benefit (hours saved / defects prevented / steps eliminated).',0,1,'2026-06-01 09:00:00','2026-08-14 11:22:08',0,NULL,1,0),(28,6,'Requirement Clarification Effectiveness','≥ 90% clear without rework','higher_better',90.00,80.00,70.00,'Percentage','monthly','Jira','CARIT-18093 + rework root-cause tags','((Total reqs − reqs causing rework from misunderstanding) ÷ total reqs) × 100, monthly. Rework tagged in Jira with root cause.',1,1,'2026-06-01 09:00:00',NULL,0,NULL,NULL,0),(29,6,'Mentoring & Knowledge-Transfer Outcome','≥ 1 skill improvement/mentee/qtr','higher_better',1.00,1.00,0.00,'Count','quarterly','Team review records','TBD — confirm in pre-go-live workshop (BRD §13.3)','Per mentee, document one skill area with before/after evidence (e.g. independently resolved a class of issue previously escalated).',0,1,'2026-06-01 09:00:00','2026-08-14 11:21:55',0,NULL,1,0),(30,6,'Applied Learning Outcome','≥ 1 applied result/month','higher_better',1.00,1.00,0.00,'Count','monthly','Training sheet + Jira','INT-9 / Training sheet','For each learning item, link a Jira where the knowledge was applied and the measurable result (e.g. resolved 40% faster).',0,1,'2026-06-01 09:00:00','2026-08-14 11:27:23',0,NULL,1,0),(31,7,'Coding Standards Compliance (Automated)','≥ 95% commits pass checks','higher_better',95.00,90.00,80.00,'Percentage','per_commit','CI linter (ESLint/Checkstyle/PMD)','TBD — confirm in pre-go-live workshop (BRD §13.3)','CI-integrated linter violation rate per commit — automated, real-time. (clean commits ÷ total commits) × 100.',0,1,'2026-06-01 09:00:00','2026-08-14 11:27:15',0,NULL,1,0),(32,7,'Documentation Currency & Review Coverage','≥ 90% docs; 100% critical reviewed','higher_better',90.00,80.00,70.00,'Percentage','monthly','Jira \'Doc Updated\' field + Git','TBD — confirm in pre-go-live workshop (BRD §13.3)','Jira \'Doc Updated\' field as Done-gate + Git branch-protection enforcing review on critical stories. (compliant ÷ required) × 100.',0,1,'2026-06-01 09:00:00','2026-08-14 11:22:20',0,NULL,1,0),(33,8,'Complete assigned technology trainings','Greate than equal to 85%','higher_better',85.00,80.00,70.00,'Percentage','monthly','Planning sheet','URL','',1,1,'2026-07-20 12:35:26','2026-07-20 12:35:26',0,1,1,0),(34,9,'Task Completion Within Estimate Definition','','higher_better',75.00,60.00,50.00,'Percentage','bi_weekly','Jira + weekly worklog (planned vs logged hours)','','Task Completion Within Estimate (%) = (Number of Tasks Completed Within Original Estimate ÷ Total Tasks Completed) × 100',1,1,'2026-07-22 21:17:02','2026-07-22 21:17:02',0,1,1,0),(35,9,'Rework / Review Rejection Rate Definition','<=30','lower_better',30.00,NULL,41.00,'Percentage','bi_weekly','Jira review transitions / mentor log','','Rework / Review Rejection Rate (%) =\n(Submissions Returned for Rework ÷ Total Submitted Tasks) ×100',1,1,'2026-07-22 22:06:21','2026-07-22 22:12:29',0,1,1,0),(36,9,'Worklog & Standup Discipline','>=95','higher_better',95.00,85.00,75.00,'Percentage','weekly','Kanban worklog export','','Worklog & Standup Discipline (%) =\n(Compliant Working Days ÷ Total Working Days) ×100',1,1,'2026-07-22 22:22:58','2026-07-22 22:22:58',0,1,1,0),(37,9,'Feature Completion Rate','>=90','higher_better',90.00,80.00,70.00,'Percentage','bi_weekly','jira sprint Board / weekly Worklog sheet','','Completed Feature Development / Assigned Feature Development x 100 = % of Contribution in Feature Development\n',1,1,'2026-07-22 22:46:19','2026-07-22 22:46:19',0,1,1,0),(38,10,'Bug Resolution Rate','>=85','higher_better',85.00,75.00,65.00,'Percentage','weekly','JIRA sprint Board','','Resolved bugs / assigned bugs  x  100',1,1,'2026-07-22 23:26:36','2026-07-22 23:26:36',0,1,1,0),(39,10,'Test Case Excution','>=95','higher_better',95.00,90.00,80.00,'Percentage','weekly','Jira','','Actual Excuted Test Cases /  Assigned Test cases  x   100',1,1,'2026-07-22 23:29:39','2026-07-22 23:29:39',0,1,1,0),(40,10,'Root Cause Analysis Completion','>=90','higher_better',90.00,80.00,70.00,'Percentage','bi_weekly','Jira Bug Ticket','','Root Cause Analysis Completion (%) =\n(Completed RCA Documents ÷ Assigned RCA Tasks) × 100',1,1,'2026-07-22 23:44:13','2026-07-22 23:44:13',0,1,1,0),(41,1,'Delivery Commitment Accuracy (Scrum Team Nikhil)','≥ 85% (senior) / ≥ 90% (lead)','higher_better',85.00,80.00,70.00,'Percentage','monthly','Sprint','','(Delivered planned items ÷ committed planned items) × 100, monthly. Track unplanned urgent work separately so genuine commitment misses are visible.',1,1,'2026-07-30 12:41:38','2026-07-30 12:42:01',0,1,1,1),(42,1,'Delivery Commitment Accuracy (Scrum Team Devdatta)','≥ 85% (senior) / ≥ 90% (lead)','higher_better',85.00,80.00,70.00,'Percentage','monthly','Sprint','','(Delivered planned items ÷ committed planned items) × 100, monthly. Track unplanned urgent work separately so genuine commitment misses are visible.',1,1,'2026-07-30 12:42:53','2026-07-30 12:42:53',0,1,1,1),(43,2,'Permanent Fix Ratio (Kanban)','≥ 90% permanent fixes','higher_better',90.00,85.00,75.00,'Percentage','monthly','Jira (fix-type field)','Jira release note & development notes','(Permanent fixes ÷ total fixes) × 100, monthly. Requires new mandatory Jira \'fix type\' (Permanent/Workaround) field set at closure.',0,1,'2026-08-27 05:16:26','2026-09-04 11:45:23',0,24,24,1);
